class SmartHome {
  + Address : string
}

class Room {
  + Name : string
}

abstract class Device {
  + DeviceIdentifier : string
}

class Sensor extends Device {
}

class Actuator extends Device {
}

class SensorReading {
  + MeasuredValue : float
  + Timestamp : datetime
}

class ControlCommand {
  + CommandName : string
  + Status : string
  + Timestamp : datetime
}

class ActivityLog {
}

class AutomationRule {
  + Timestamp : datetime
  + canEdit() : boolean
  + activate()
  + deactivate()
}

class Precondition {
}

class Action {
}

class Owner {
}

SmartHome "1" *-- "1..*" Room
Room "1" -- "0..*" Device
SmartHome "1" -- "*" ActivityLog
Sensor "1" -- "*" SensorReading
Actuator "1" -- "*" ControlCommand
SensorReading "*" -- "1" ActivityLog
ControlCommand "*" -- "1" ActivityLog
Owner "1" -- "*" AutomationRule : manages
AutomationRule "1" -- "1" Precondition
AutomationRule "1" -- "1" Action
AutomationRule "0..*" -- "0..*" AutomationRule : depends on / conflicts with

@enduml

